DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_1','RomanGladius Network[NEWLINE]Population management and a stable wide economy[NEWLINE]Science or Diplomacy; Culture from a mature network[NEWLINE][NEWLINE]Grow Players, keep staffing proportional to population, and maintain Reputation so the economy can reach higher thresholds. Expansion is valuable only when the new Server can pay its launch and management costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_2','Grow the capital and establish a treasury before ordering another Server Owner. Read its population and Gold costs before committing. Use the free Console and early milestones to support growth rather than assuming normal Settler economics.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_3','Check staff coverage whenever a city crosses a population threshold. Appoint enough Moderators without overmoderating, use an Administrator where its support justifies upkeep, and resolve incidents before weak Reputation becomes a growth spiral.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_4','Protect the largest Servers and keep new cities manageable. Population milestones and accumulated yields can finance conventional research, diplomacy or military production; the dashboard still needs attention during a war.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_5','- Population adds Gold, Science and Culture through several thresholds.[NEWLINE]- Healthy Reputation can reinforce growth and income.[NEWLINE]- Persistent milestones reward developing the network as a whole.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_6','- Server Owners impose unusual population, Production and launch-Gold costs.[NEWLINE]- Understaffing and overstaffing can both damage Reputation.[NEWLINE]- Low Reputation can slow growth and lead to departures, weakening the yield engine.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_7','- Pressure food tiles and major population centres instead of chasing only peripheral units.[NEWLINE]- Force expensive emergency spending when a launch or staffing expansion is planned.[NEWLINE]- Take advantage of a troubled Server before its staffing and growth recover.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_8','- Applying an ordinary cheap-Settler expansion plan to Server Owners.[NEWLINE]- Ignoring the coverage increase after population growth.[NEWLINE]- Hiring as many Moderators as possible without checking overmoderation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: A safe mature Server network can leverage population scaling beyond Saba''s modest site-based additions; the opening must still survive.[NEWLINE][NEWLINE]Pigeon Republic: Population yields continue without a caravan connection, making a low-trade or disrupted-trade environment a relative opportunity.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Pressure on large economic cities can amplify the practical cost of keeping growth, staffing and income stable.[NEWLINE][NEWLINE]Viltrum: A first conquest of a large, expensive Server is a serious loss and can also feed Viltrum''s campaign momentum.');
