INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_BACKGROUND','Grow Players, keep staffing proportional to population, and maintain Reputation so the economy can reach higher thresholds. Expansion is valuable only when the new Server can pay its launch and management costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_CIV_ROMAN_GLADIUS_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_BACKGROUND','Grow Players, keep staffing proportional to population, and maintain Reputation so the economy can reach higher thresholds. Expansion is valuable only when the new Server can pay its launch and management costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_LEADER_ROMAN_GLADIUS_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_STRATEGY','Grow Players, keep staffing proportional to population, and maintain Reputation so the economy can reach higher thresholds. Expansion is valuable only when the new Server can pay its launch and management costs.[NEWLINE][NEWLINE]Grow the capital and establish a treasury before ordering another Server Owner. Read its population and Gold costs before committing. Use the free Console and early milestones to support growth rather than assuming normal Settler economics.[NEWLINE][NEWLINE]Check staff coverage whenever a city crosses a population threshold. Appoint enough Moderators without overmoderating, use an Administrator where its support justifies upkeep, and resolve incidents before weak Reputation becomes a growth spiral.[NEWLINE][NEWLINE]Protect the largest Servers and keep new cities manageable. Population milestones and accumulated yields can finance conventional research, diplomacy or military production; the dashboard still needs attention during a war.');
