INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_TEXT_1','RomanGladius Network[NEWLINE]Population management and a stable wide economy[NEWLINE]Science or Diplomacy; Culture from a mature network[NEWLINE][NEWLINE]Grow Players, keep staffing proportional to population, and maintain Reputation so the economy can reach higher thresholds. Expansion is valuable only when the new Server can pay its launch and management costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_TEXT_2','Grow the capital and establish a treasury before ordering another Server Owner. Read its population and Gold costs before committing. Use the free Console and early milestones to support growth rather than assuming normal Settler economics.[NEWLINE][NEWLINE]Check staff coverage whenever a city crosses a population threshold. Appoint enough Moderators without overmoderating, use an Administrator where its support justifies upkeep, and resolve incidents before weak Reputation becomes a growth spiral.[NEWLINE][NEWLINE]Protect the largest Servers and keep new cities manageable. Population milestones and accumulated yields can finance conventional research, diplomacy or military production; the dashboard still needs attention during a war.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_ROMANGLADIUSNETWORK_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Saba: A safe mature Server network can leverage population scaling beyond Saba''s modest site-based additions; the opening must still survive.[NEWLINE][NEWLINE]Pigeon Republic: Population yields continue without a caravan connection, making a low-trade or disrupted-trade environment a relative opportunity.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Filthy Realm: Pressure on large economic cities can amplify the practical cost of keeping growth, staffing and income stable.[NEWLINE][NEWLINE]Viltrum: A first conquest of a large, expensive Server is a serious loss and can also feed Viltrum''s campaign momentum.');
